\begin{tikzpicture}[font=\sffamily, scale=1.2]
    % Coordinates for the wedge (slope rising to the right)
    % Let the bottom-left corner be (0,0)
    % Angle is 30 degrees. Let base length be about 6cm.
    \coordinate (O) at (0,0); % bottom left corner (right angle)
    \coordinate (A) at (5.5,0); % bottom right corner
    \coordinate (B) at (5.5,{5.5*tan(30)}); % top corner

    % Draw the wedge
    \draw[thick] (O) -- (A) -- (B) -- cycle;

    % Ground surface under the wedge
    \surface{(O)}{(A)}{1}

    % 30 degree angle mark at bottom left
    \draw (1,0) arc (0:30:1);
    \node at (1.3,0.3) {$30^\circ$};

    % 4.0 kg block on the slope
    % Position the block along the slope
    \def\d{2.5} % distance up the slope
    \coordinate (CenterBlock) at ({\d*cos(30)}, {\d*sin(30)});

    % We want the block to be drawn rotated by 30 degrees
    \begin{scope}[shift={(CenterBlock)}, rotate=30]
        % Draw block as a rectangle centered at origin
        \draw[thick] (-0.5,-0.35) rectangle (0.5,0.35);
        \node at (0,0) {$4.0\text{ kg obat}$}; % wait, just 4.0 kg as per text
    \end{scope}
    % Correcting node for 4.0 kg block
    \begin{scope}[shift={(CenterBlock)}, rotate=30]
        \node at (0,0) {$4.0\text{ kg}$};
    \end{scope}

    % String from block up to the pulley
    % Pulley at B
    \coordinate (Pulley) at (B);

    % Top edge of block where string connects (rotated)
    \coordinate (BlockTop) at ({(\d+0.5)*cos(30)}, {(\d+0.5)*sin(30)});

    % Draw string from block to pulley
    \draw[thick] (BlockTop) -- (Pulley);

    % Pulley: small circle at B
    \draw[thick, fill=white] (Pulley) circle (0.2);
    \fill (Pulley) circle (0.05);

    % String hanging vertically down from pulley to 3.0 kg mass
    \coordinate (HangStart) at ($(Pulley)+(0.2,0)$); % tangential to right side of pulley? Or just from center/edge
    % Let's make it drop from the right side of the pulley
    \coordinate (StringDownTop) at ($(B)+(0.2,0)$);
    \coordinate (StringDownBot) at ($(B)+(0.2,-1.8)$);
    \draw[thick] (StringDownTop) -- (StringDownBot);

    % 3.0 kg hanging mass
    \begin{scope}[shift={(StringDownBot)}]
        \draw[thick] (-0.4,-0.4) rectangle (0.4,0.4);
        \node at (0,0) {$3.0\text{ kg}$};
    \end{scope}

    % Labels with pointers
    % "smooth pulley" pointing to pulley
    \node[above right=0.3cm and 0.4cm of Pulley] (pLabel) {smooth pulley};
    \draw[-Stealth, thin] (pLabel) -- (Pulley);

    % "rough plane" pointing to the wedge slope
    \coordinate (PlaneMid) at ({2*cos(30)}, {2*sin(30)});
    \node[above left=0.6cm and 0.4cm of PlaneMid] (planeLabel) {rough plane};
    \draw[-Stealth, thin] (planeLabel) -- (PlaneMid);

    % Caption below the figure
    \node at (2.75,-1.2) {Fig. 1.1};

\end{tikzpicture}

